contract InvMutTest {
    C c;
    constructor(C _c) { c = _c; }
    function run(address target, uint256 value, bytes calldata data, bytes32 predecessor, bytes32 salt, uint256 delay, address proposer) public payable {
        // ensure proposer's role: constructor of C gave roles to some addresses, but msg.sender here is this contract;
        // we can't change roles externally, so we assert properties that don't depend on having PROPOSER_ROLE.
        // However, schedule requires caller to have PROPOSER_ROLE and will revert otherwise. We capture that behavior.

        // Compute id using public hashOperation
        bytes32 id = c.hashOperation(target, value, data, predecessor, salt);

        // Record pre-state
        uint256 beforeTs = c.getTimestamp(id);
        uint256 minDelay = c.getMinDelay();

        bool reverted;
        // attempt to call schedule as this contract (msg.sender = this)
        try c.schedule(target, value, data, predecessor, salt, delay) {
            reverted = false;
        } catch {
            reverted = true;
        }

        // read post-state
        uint256 afterTs = c.getTimestamp(id);

        // General rule (single assert): Either the call reverted (because caller lacks PROPOSER_ROLE or other require),
        // or it succeeded and then beforeTs must have been 0 (operation not previously scheduled), delay >= minDelay,
        // and afterTs equals block.timestamp + delay and isOperation returns true.
        assert(
            reverted
            || (
                beforeTs == 0
                && delay >= minDelay
                && afterTs == block.timestamp + delay
                && c.isOperation(id)
            )
        );
    }
    receive() external payable {}
}

contract InvMutTest {
    C c;
    constructor(C _c) { c = _c; }

    // We take parameters that match C.execute signature and also allow funding the call.
    function run(address target, uint256 value, bytes calldata data, bytes32 predecessor, bytes32 salt, uint256 fund) public payable {
        // ensure this contract has enough balance if it will forward ETH
        if (fund > 0) require(address(this).balance >= fund);

        // compute operation id
        bytes32 id = c.hashOperation(target, value, data, predecessor, salt);

        // read timestamp before
        uint256 tsBefore = c.getTimestamp(id);

        bool reverted;
        // try to execute; must be a top-level call that may change state
        try c.execute{value: fund}(target, value, data, predecessor, salt) {
            reverted = false;
        } catch {
            reverted = true;
        }

        // read timestamp after
        uint256 tsAfter = c.getTimestamp(id);

        // General rule: if execute did not revert then the operation is done and timestamp equals 1 (_DONE_TIMESTAMP)
        assert(reverted || (c.isOperationDone(id) && tsAfter == 1 && tsAfter != tsBefore));
    }

    receive() external payable {}
}

contract InvMutTest {
    C c;
    constructor(C _c) { c = _c; }

    // We test schedule which requires sender to have PROPOSER_ROLE; the test contract does not have that role
    // so we will first grant ourselves the PROPOSER_ROLE by calling c.schedule from an address that has it.
    // However, per constraints we cannot change msg.sender; instead we use the constructor-provided c which
    // on deployment gave TIMELOCK_ADMIN_ROLE to its deployer and the contract itself. To ensure the test
    // can call schedule we require that the provided proposer's role admin is the zero address role and
    // that this contract already has PROPOSER_ROLE by calling schedule directly and observing success or revert.
    // To keep things simple and within allowed interactions we assert the general property about schedule's effect
    // only in the successful (non-reverted) case. The function takes the exact schedule parameters.

    function run(address target, uint256 value, bytes calldata data, bytes32 predecessor, bytes32 salt, uint256 delay) public payable {
        // require a reasonable bound to help the checker (avoid huge delays)
        require(delay <= 2**64 - 1);
        // compute id via public hashOperation
        bytes32 id = c.hashOperation(target, value, data, predecessor, salt);

        // read timestamp before
        uint256 tsBefore = c.getTimestamp(id);

        bool reverted;
        // call schedule as a top-level statement; may revert if caller lacks PROPOSER_ROLE
        try c.schedule(target, value, data, predecessor, salt, delay) {
            reverted = false;
        } catch {
            reverted = true;
        }

        // read timestamp after
        uint256 tsAfter = c.getTimestamp(id);

        // General rule: if schedule did not revert then the operation is scheduled: isOperation(id) == true and timestamp > 0
        assert(reverted || (c.isOperation(id) && tsAfter > 0 && tsAfter != tsBefore));
    }

    receive() external payable {}
}
